<script setup>
import {computed,ref,watch,onMounted,nextTick,onBeforeUnmount} from 'vue'
import * as echarts from 'echarts/core'
import {LineChart} from 'echarts/charts'
import {GridComponent,TooltipComponent} from 'echarts/components'
import {CanvasRenderer} from 'echarts/renderers'
echarts.use([LineChart,GridComponent,TooltipComponent,CanvasRenderer])
function readSetting(key){try{return localStorage.getItem(key)}catch{return null}}
const savedMode=readSetting('aquant.mode')
const mode=ref(savedMode==='live'?'live':'demo')
function readCapital(mode){const value=Number(readSetting(`aquant.capital.${mode}`));return Number.isFinite(value)&&value>=10000&&value<=1e10?value:200000}
const capital=ref(readCapital(mode.value)),report=ref(null),error=ref(''),busy=ref(false),tab=ref('daily'),test=ref(null),chartEl=ref(null)
watch(capital,value=>{if(typeof value==='number'&&Number.isFinite(value)&&value>=10000&&value<=1e10){try{localStorage.setItem(`aquant.capital.${mode.value}`,String(value))}catch{}}},{flush:'sync'})
function changeMode(){ledgerPage.value=1;capital.value=readCapital(mode.value);try{localStorage.setItem('aquant.mode',mode.value)}catch{};refresh()}
const form=ref({code:'600001',side:'BUY',quantity:100,price:12,trade_date:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})})
const adxFilter=ref(false),strictFilter=ref(true),amplitudeFilter=ref(true),marketFilter=ref(true),topN=ref(3),modelFilter=ref('ALL'),rank=ref('liquidity')
const model=ref('S1'),testCode=ref('600001');let chart
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const j=await r.json();if(!r.ok)throw Error(typeof j.detail==='string'?j.detail:JSON.stringify(j.detail));return j}
async function refresh(){busy.value=true;error.value='';test.value=null;chart?.dispose();chart=null;try{report.value=await api(`daily?mode=${mode.value}&capital=${capital.value}&adx_filter=${adxFilter.value}&strict_filter=${strictFilter.value}&amplitude_filter=${amplitudeFilter.value}&market_filter=${marketFilter.value}&top_n=${topN.value}&model_filter=${modelFilter.value}&rank=${rank.value}`)}catch(e){report.value=null;error.value=e.message}finally{busy.value=false}}
async function record(){busy.value=true;error.value='';try{await api('trades',{...form.value,mode:mode.value,request_id:crypto.randomUUID()});await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
const ledgerPage=ref(1),pageSize=10
const sortedLedger=computed(()=>[...(report.value?.ledger??[])].sort((a,b)=>b.trade_date.localeCompare(a.trade_date)||b.id-a.id))
const ledgerPages=computed(()=>Math.max(1,Math.ceil(sortedLedger.value.length/pageSize)))
const pagedLedger=computed(()=>sortedLedger.value.slice((ledgerPage.value-1)*pageSize,ledgerPage.value*pageSize))
watch(ledgerPages,pages=>{ledgerPage.value=Math.min(ledgerPage.value,pages)})
const pnlClass=value=>value>0?'pnl-positive':value<0?'pnl-negative':''
const unrealizedPnl=computed(()=>(report.value?.holdings??[]).reduce((sum,h)=>sum+(h.pnl??0),0))
const realizedPnl=computed(()=>(report.value?.ledger??[]).reduce((sum,t)=>sum+(t.realized_pnl??0),0))
const totalPnl=computed(()=>unrealizedPnl.value+realizedPnl.value)
const totalRate=computed(()=>{const c=Number(capital.value);return Number.isFinite(c)&&c>0?totalPnl.value/c:null})
const pnlIncomplete=computed(()=>(report.value?.holdings??[]).some(h=>h.pnl==null))
async function clearPositions(){
  const selectedMode=mode.value
  if(!window.confirm(`确认删除${selectedMode==='demo'?'示例':'正式'}模式的所有持仓？历史成交记录保留；此操作仅重置本地持仓，不代表实际卖出。`))return
  busy.value=true;error.value=''
  try{await api('positions/clear',{mode:selectedMode});await refresh()}catch(e){error.value=e.message}finally{busy.value=false}
}
async function runTest(){busy.value=true;error.value='';try{test.value=await api('backtest',{code:testCode.value,model:model.value,mode:mode.value,capital:capital.value,adx_filter:adxFilter.value,strict_filter:strictFilter.value});await nextTick();chart?.dispose();chart=echarts.init(chartEl.value);chart.setOption({tooltip:{trigger:'axis'},grid:{left:70,right:24,top:24,bottom:36},xAxis:{type:'category',data:test.value.curve.map(x=>x.date)},yAxis:{type:'value',scale:true},series:[{type:'line',symbol:'none',data:test.value.curve.map(x=>x.equity),lineStyle:{color:'#2dd4bf'},areaStyle:{color:'#2dd4bf',opacity:.12}}]})}catch(e){error.value=e.message}finally{busy.value=false}}
function resize(){chart?.resize()}onMounted(()=>{refresh();window.addEventListener('resize',resize)});onBeforeUnmount(()=>{chart?.dispose();window.removeEventListener('resize',resize)})
const money=x=>x==null?'无法估值':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:2}),pct=x=>x==null?'未知':(x*100).toFixed(2)+'%'
</script>
<template>
<div class="shell"><aside><div class="brand">A<span>·</span>Quant <small>V1 / LOCAL</small></div><p class="tagline">先管理持仓，再寻找机会。</p><button :class="{active:tab==='daily'}" @click="tab='daily'">01　每日工作台</button><button :class="{active:tab==='trade'}" @click="tab='trade'">02　成交与持仓</button><button :class="{active:tab==='test'}" @click="tab='test'">03　策略回测</button><div class="aside-note">沪深主板 + 创业板<br>规则驱动 · 人工执行<br>本地账本 · 无自动交易</div></aside>
<main><header><div><div class="eyebrow">A-SHARE RESEARCH WORKSPACE</div><h1>{{tab==='daily'?'收盘后的决策，从持仓开始':tab==='trade'?'记录已成交的每一笔交易':'让规则接受历史检验'}}</h1></div><span class="badge">{{mode==='demo'?'示例模式':'行情缓存模式'}}</span></header>
<div class="toolbar"><label>数据<select v-model="mode" @change="changeMode"><option value="demo">合成示例行情</option><option value="live">AKShare 本地缓存</option></select></label><label>账户总权益（含现金）<input v-model.number="capital" type="number" min="10000"></label><button @click="refresh" :disabled="busy">{{busy?'处理中…':'重新分析'}}</button><label><input type="checkbox" v-model="adxFilter">S1启用ADX过滤（研究对照）</label><label><input type="checkbox" v-model="strictFilter">严格复筛</label><label><input type="checkbox" v-model="amplitudeFilter">振幅过滤</label><label><input type="checkbox" v-model="marketFilter">弱市暂停</label><label>策略<select v-model="modelFilter"><option value="ALL">全部（S1+S2）</option><option value="S1">仅 S1 突破</option><option value="S2">仅 S2 回调</option></select></label><label>每日名额<select v-model.number="topN"><option :value="3">3</option><option :value="5">5</option><option :value="10">10</option></select></label><label>排序依据<select v-model="rank"><option value="liquidity">成交额（默认）</option><option value="volume">缩量优先</option><option value="score">质量分</option></select></label><span v-if="report">数据截至 {{report.as_of}}</span></div>
<div v-if="error" role="alert" class="alert">{{error}}</div><template v-if="report"><div class="alert" v-if="!report.strategy || !report.market">后端仍是旧版（缺少市场状态/候选名额字段），请在旧服务终端按Ctrl+C，再双击run-start.cmd；仅刷新页面无法更新后端。</div><div class="panel" v-if="report.data_quality">目标日K线覆盖 {{report.data_quality.covered}} / {{report.data_quality.total}}（{{pct(report.data_quality.ratio)}}，最低 {{pct(report.data_quality.minimum)}}）；分母为当前缓存股票数，并非全市场上市总数。<template v-if="report.sync_info"><p>行情源：{{report.sync_info.provider==='tencent'?'腾讯日线 / 新浪名单':report.sync_info.provider==='eastmoney'?'东方财富':mode==='demo'?'合成示例':'未知'}} · 同步时间：{{report.sync_info.fetched_at || '未记录'}} · 同步错误 {{report.sync_info.error_count}} 项 · {{report.sync_info.complete?'同步完整':'同步未完整'}}</p><details v-if="report.sync_info.error_count"><summary>查看同步错误（最多显示 10 项）</summary><p v-for="(e,i) in report.sync_info.errors" :key="i">{{e.code || '同步'}}：{{e.error}}</p></details></template><p>覆盖率不足或同步存在错误时暂停新计划；缺少更新不会自动认定为停牌。</p></div><div class="panel" v-if="report.market">市场状态 <b>{{report.market.regime}}</b> · 宽度 {{(report.market.breadth*100).toFixed(0)}}%（{{report.market.samples}}/{{report.market.total}} 只站上自身MA20）· 等权指数{{report.market.index_above_ma20?'在MA20上方':'在MA20下方'}}<template v-if="!report.market.trustworthy">　<span class="danger">样本不足一半，未据此拦截计划</span></template></div><div class="panel" v-if="report.strategy">策略版本 {{report.strategy.version}} · {{report.strategy.strict_filter?'严格复筛开启':'基础筛选'}} · 命中 S1 {{report.candidates_by_model?.S1 ?? 0}} / S2 {{report.candidates_by_model?.S2 ?? 0}} 条<template v-if="modelFilter!=='ALL'">（当前只显示 {{modelFilter}}：{{report.candidates_total ?? report.candidates.length}} 条）</template>，按当前排序依据取前 {{report.candidate_limit ?? report.candidates.length}} 条（非收益排名）· 振幅上限 S1 {{report.signal_stats?.amplitude_limits?.S1 ?? '—'}}×ATR / S2 {{report.signal_stats?.amplitude_limits?.S2 ?? '—'}}×ATR</div><div class="alert" v-if="report.warnings.length"><b>数据与执行限制</b><div v-for="w in report.warnings" :key="w">{{w}}</div></div>
<section v-show="tab==='daily'"><div class="metrics"><article><small>当前未清仓</small><strong>{{report.holdings.length}} <em>只</em></strong></article><article><small>已知持仓市值</small><strong>¥ {{money(report.risk.known_market_value)}}</strong></article><article><small>组合仓位</small><strong>{{pct(report.risk.exposure)}}</strong></article><article><small>总收益（浮动+已实现）</small><strong :class="pnlClass(totalPnl)">¥ {{money(totalPnl)}}</strong><small>浮盈 {{money(unrealizedPnl)}} · 已实现 {{money(realizedPnl)}}<template v-if="pnlIncomplete"> · 含无法估值持仓</template></small></article><article><small>收益率（÷账户权益）</small><strong :class="pnlClass(totalRate)">{{pct(totalRate)}}</strong></article><article><small>通过股票池筛选</small><strong>{{report.pool_count}} <em>只</em></strong></article></div>
<div class="section-title"><h2><i>01</i> 持仓逐一复核</h2><div class="holding-actions"><span>日报总是先处理全部未卖出持仓</span><button class="delete-button" :disabled="busy || !report.holdings.length" @click="clearPositions">删除所有持仓</button></div></div><div v-if="!report.holdings.length" class="empty">尚无已报告持仓。请在「成交与持仓」登记实际成交，示例账本与正式账本独立。</div><div class="holding" v-for="p in report.holdings" :key="p.code"><div><b>{{p.code}}</b>　{{p.quantity}} 股 · 均价 {{money(p.avg_cost)}}<span class="badge">{{p.status}}</span></div><p>市值 ¥ {{money(p.market_value)}}　浮动盈亏 <span :class="pnlClass(p.pnl)">¥ {{money(p.pnl)}}</span><template v-if="p.last_known_market_value!=null">　最后已知估值 ¥ {{money(p.last_known_market_value)}}（{{p.valuation_date}}，非当日估值）</template>　止损参考 {{money(p.stop)}}</p><p class="holding-stats" v-if="p.status==='已分析'"><span v-if="p.dist_stop_pct!=null">距止损 <b>{{pct(p.dist_stop_pct)}}</b><template v-if="p.dist_stop_atr!=null">（{{p.dist_stop_atr}}×ATR）</template></span><span v-if="p.dist_ma20_pct!=null">距MA20 <b>{{pct(p.dist_ma20_pct)}}</b><template v-if="p.dist_ma20_atr!=null">（{{p.dist_ma20_atr}}×ATR）</template></span><span v-if="p.holding_days!=null">已持有 <b>{{p.holding_days}}</b> 个交易日</span><span v-if="p.peak_drawdown_pct!=null">距持仓高点回撤 <b>{{pct(p.peak_drawdown_pct)}}</b><template v-if="p.peak_drawdown_atr!=null">（{{p.peak_drawdown_atr}}×ATR）</template></span></p><div class="advice" :class="'grade-'+(p.grade==='退出'?'exit':p.grade==='减半'?'half':p.grade==='观察'?'watch':'none')"><span class="grade-tag" v-if="p.grade">{{p.grade}}</span>{{p.action}}</div></div>
<div class="section-title"><h2><i>02</i> 组合风险</h2></div><div class="panel">单股最大权重 {{pct(report.risk.largest_weight)}} · 上限20% · 总仓位上限70%<p v-for="w in report.risk.warnings" :key="w" class="danger">{{w}}</p><p>总权益由用户填写；市值缺失时仓位显示未知，新增计划全部阻断。价格止损无法保证成交。</p></div>
<div class="section-title"><h2><i>03</i> 新机会与条件计划</h2><span>S1 唐奇安突破 / S2 ATR回调</span></div><div class="table-wrap"><table><thead><tr><th>股票 / 模型</th><th>入选依据</th><th>优先级</th><th>收盘参考</th><th>止损 / 每股风险距离</th><th>参考数量</th><th>计划状态</th></tr></thead><tbody><tr v-for="c in report.candidates" :key="c.code+c.model"><td><b>{{c.code}}</b><br>{{c.name}} · {{c.model}}</td><td>{{c.reason}}<small>{{c.execution}}</small><small v-if="c.day_range_atr!=null">信号日振幅 {{c.day_range_atr}}×ATR</small></td><td><b>{{c.rank_score}}/{{c.rank_max}}</b><small>{{c.rank_reason}}</small></td><td>{{c.reference_close}}</td><td>{{c.stop_reference}} / {{money(c.risk_distance)}}</td><td>{{c.suggested_quantity}} 股</td><td>{{c.plan_status}}</td></tr><tr v-if="!report.candidates.length"><td colspan="7">当前没有满足条件的股票（可能被振幅过滤、弱市暂停或「策略」筛选挡住）。把「策略」切回全部、或放宽过滤后再点「重新分析」。</td></tr></tbody></table></div><p v-if="report.candidate_limit && report.candidates_total>report.candidates.length">按当前排序依据，另有 <b>{{report.candidates_total-report.candidates.length}}</b> 条未进入当日名额（仅备查，不参与预算分配）。可用「每日名额」调大查看。</p><details><summary>查看排除记录与规则</summary><p>严格复筛：S1增加ADX≥25、+DI>−DI、RSI≤75、距SMA20≤3ATR；S2增加ADX≥20、+DI>−DI、收盘较前日上涨。不会强制凑够或保留一半；关闭可与基础筛选对照。</p><p>S1：收盘突破前20日上轨＋量比≥1.3＋高于SMA20。S2：SMA20高于SMA60且上行＋距SMA20为0–1ATR＋RSI14为40–60。ATR/RSI/ADX使用Wilder平滑，周期14。新计划止损为2ATR，不设预测止盈；回测按止损、SMA20或持有期限退出，无固定止盈。持仓ATR线按当日重算，非锁定或追踪止损。参数尚未验证收益。</p><p>20日平均成交额≥5000万元；至少60根日线；排除科创/北交/ST/退市/停牌/异常行情；不限制市值。阈值在 backend/engine.py 配置。</p><p v-for="s in report.excluded" :key="s.code">{{s.code}} · {{s.reason}}</p></details></section>
<section v-show="tab==='trade'"><div class="panel"><h2>仅报告已经发生的成交</h2><p>登记后才改变持仓。扫描、止损和回测都不会修改账本。部分卖出后继续分析剩余仓位。</p><form @submit.prevent="record" class="trade-form"><label>六位股票代码<input v-model="form.code" pattern="[0-9]{6}" required></label><label>成交方向<select v-model="form.side"><option value="BUY">已买入</option><option value="SELL">已卖出</option></select></label><label>成交数量<input v-model.number="form.quantity" type="number" min="1" step="1" required></label><label>成交价格<input v-model.number="form.price" type="number" min="0.01" step="0.01" required></label><label>成交日期<input v-model="form.trade_date" type="date" required></label><button :disabled="busy">登记{{mode==='demo'?'示例':'实际'}}成交</button></form></div><h2>成交账本</h2><p class="ledger-note">卖出盈亏按卖出前加权平均成本计算，未扣手续费和税费；日期从新到旧排列。</p><div class="table-wrap"><table><thead><tr><th>日期</th><th>代码</th><th>方向</th><th>数量</th><th>价格</th><th>卖出盈亏（元）</th></tr></thead><tbody><tr v-for="t in pagedLedger" :key="t.id"><td>{{t.trade_date}}</td><td>{{t.code}}</td><td>{{t.side==='BUY'?'买入':'卖出'}}</td><td>{{t.quantity}}</td><td>{{t.price}}</td><td :class="pnlClass(t.realized_pnl)">{{t.side==='SELL' && t.realized_pnl!=null?money(t.realized_pnl):'—'}}</td></tr><tr v-if="!sortedLedger.length"><td colspan="6">暂无成交记录</td></tr></tbody></table></div><nav class="pagination" aria-label="成交账本分页"><span>共 {{sortedLedger.length}} 条 · 每页 10 条 · 第 {{ledgerPage}} / {{ledgerPages}} 页</span><button :disabled="ledgerPage<=1" @click="ledgerPage--">上一页</button><button :disabled="ledgerPage>=ledgerPages" @click="ledgerPage++">下一页</button></nav></section>
<section v-show="tab==='test'"><div class="panel"><h2>单股规则回测</h2><p>收盘产生信号，次日开盘模拟成交；包含手续费、滑点、卖出税费和保守涨跌停过滤。示例行情不反映真实收益。</p><div class="toolbar"><label>股票代码<input v-model="testCode" maxlength="6"></label><label>策略<select v-model="model"><option>S1</option><option>S2</option></select></label><button :disabled="busy" @click="runTest">运行回测</button></div></div><template v-if="test"><div class="metrics"><article><small>模拟累计收益</small><strong>{{pct(test.total_return)}}</strong></article><article><small>最大回撤</small><strong>{{pct(test.max_drawdown)}}</strong></article><article><small>成交笔数 / 未平仓股数</small><strong>{{test.trades.length}} / {{test.open_quantity}}</strong></article></div><div ref="chartEl" class="chart"></div><div class="alert"><p v-for="l in test.limitations" :key="l">{{l}}</p></div><details><summary>成交明细 / 费用假设</summary><pre>{{test.assumptions}}</pre><p v-for="(t,i) in test.trades" :key="i">{{t.date}} · {{t.side}} · {{t.quantity}} 股 · {{t.price}} · 费用 {{t.fee}}</p></details></template></section>
</template><footer>研究基线尚未通过样本外验证；候选少不代表收益更好。V1不连接券商；实际成交、公告与账户权益需人工核实。每日运行需要本机开机及任务计划配置。</footer></main></div>
</template>
